<template>
  <div class="container" v-if='loadings'>
    <div class="login_icon">
      <img src="../img/home/LOGO3.png" alt="" style="width: 100%;height: 100%;">
      <!-- <img src="../img/home/LOGO.png" alt="" style="width: 100%;height: 100%;"> -->
    </div>
    <div class="company">
      山西阳光三极科技股份有限公司
    </div>
    <div class="form-box" v-if="activateOpen">
      <div class="title-box" v-if="system == 'TFS'">
        {{ pageTitles }}
      </div>
      <div class="title-box" v-else>
        {{ pageTitle }}
      </div>
      <h2 class="login_h2">欢迎登录</h2>
      <el-form ref="loginForm" :model="form" :rules="loginRules">
        <el-form-item label="用户名" prop="username">
          <!-- <el-input v-model="form.username" required class="login_user" placeholder="请输入用户名">
            <template slot="prefix">
              <div style="width: 45px;height: 40px;border-right: 1px solid #1F77F4 ;display: flex;align-items: center;justify-content: center;">
                <img src="../img/login/icon_user.png" alt="" style="width: 16px;height: 18px;">
              </div>
            </template>
          </el-input> -->
          <el-input v-model="form.username" required prefix-icon="el-icon-user-solid" placeholder="请输入用户名"></el-input>
        </el-form-item>
        <el-form-item label="密码" prop="password">
          <!-- <el-input type="password" v-model="form.password" required show-password @keyup.enter.native="handleLogin" placeholder="请输入密码">
            <template slot="prefix">
              <div style="width: 45px;height: 40px;border-right: 1px solid #1F77F4 ;display: flex;align-items: center;justify-content: center;">
                <img src="../img/login/icon_lock.png" alt="" style="width: 16px;height: 18px;">
              </div>
            </template>
          </el-input> -->
          <el-input v-model="form.password" required prefix-icon="el-icon-lock" show-password @keyup.enter.native="handleLogin" placeholder="请输入密码"></el-input>
        </el-form-item>
        <p style="color:#fff;">验证码</p>
        <el-form-item>
          <div class="el-row" span="24">
            <div class="el-col el-col-16">
              <el-input
                type="text"
                @keyup.enter.native="handleLogin"
                maxlength="4"
                placeholder="请输入验证码"
                prefix-icon="el-icon-position"
                v-model="form.captcha"
                clearable
                autocomplete="off"
              ></el-input>
            </div>
            <div class="el-col el-col-8">
              <div class="login-code" @click="captcha">
                <img :src="captchaImg" alt="" style="width: 100%;height:100%;">
              </div>
            </div>
          </div>
        </el-form-item>
        <el-form-item>
          <!-- <el-button @click.native.prevent="handleLogin">登录</el-button> -->
          <div class="btn" @click="handleLogin">登&nbsp;&nbsp;录</div>
        </el-form-item>
      </el-form>
    </div>
    <div class="form-box" v-else>
      <div class="title-box">
        {{ pageTitle }}
      </div>
      <div class="activate">
        <span>提示：</span>
        <span>该系统尚未激活！请导入激活文件！</span>
        <!-- <span>
          <router-link style="color: greenyellow;" to="/activate2">运管中心</router-link>
        </span> -->
        <div class="btns">
          <el-upload class="upload-demo" :action="uploadAction" :auto-upload="false" :before-upload="beforeUpload" :on-change="handleChange" :show-file-list="true" :limit="1">
            <el-button type="primary" icon="el-icon-upload">导入激活文件</el-button>
          </el-upload>
        </div>
      </div>
    </div>
    <div class="btns1" v-if="!activateOpen">
      <img :src="imgjq" alt="">
    </div>
  </div>
</template>
  
<script>
import axios from 'axios';
import { activate } from '@/api/activate/index';
import axiosLogin from '../axios/login';
import Cookies from 'js-cookie'; // 导入js-cookie库，用于操作cookie
import { loginApi } from '../api/login.js';
export default {
  data() {
    return {
      loadings: false,
      uploadAction: activate.activateToLoad,
      imgjq:activate.imgjq,
      pageTitle: '视频AI识别分析管理平台',
      pageTitles: '智能钻场配置管理平台',
      // pageTitle: 'AI监管平台',
      captchaImg: '',//验证码
      form: {
        username: '',
        password: '',
        captcha:'',
      },
      loginRules: {
        username: [
          { required: true, trigger: "blur", message: "请输入您的账号" }
        ],
        password: [
          { required: true, trigger: "blur", message: "请输入您的密码" }
        ],
        captcha: [
            { required: true, trigger: "blur", message: "请输入验证码" }
        ]
      },
      // 判断系统激活与未激活的开关控制,true为激活状态，false为未激活状态
      activateOpen: true,
      system: window.wgParameter.system,
    };
  },
  created() {
    const queryString = window.location.search;
console.log(queryString);

// 创建 URLSearchParams 实例
const params = new URLSearchParams(queryString);

// 获取单个参数的值
const name = params.get('username'); 
const pwd = params.get('password');  
    if(params != '' && params != null && params != undefined){
      this.loadings = false;
      axiosLogin
            .get(this.$url.url_5000 + "/user_view/loginfree", { withcredentials:true,params: { 
              username: name,
              password: pwd,
             } })
            .then((response) => {
              // console.log(response);
              if (response.data.code === 200) {
                this.$message({
                  message: response.data.msg,
                  type: "success",
                });
                // this.$store.commit('setId',response.data.session.id)
                // this.$store.commit('setUser_id',response.data.session.user_id)
                // Cookies.set('session', response.data.session.id, { expires: 1 , path: '/',httpOnly: true  }); // 设置cookie有效期为7天
                this.$store.commit('setToken', response.data.access_token)
                this.$store.commit('setUserInfo', response.data.user_id)
                this.$store.commit('userRoleName', response.data.user_name)
                this.$store.commit('setUserInfos', response.data.user_role_id)
                this.$router.push('/')
              } else {
                this.$message({
                  message: response.data.msg,
                  type: "warning",
                });
                // if (this.system == 'JY') {
                //   this.captcha()
                // }
              }
            })
            .catch(function (response) {
              console.log(response);
            });
    }else {
      this.loadings = true;
      this.captcha()
    };
    this.getJudgment();
  },
  methods: {
    // 上传前
    beforeUpload(file) {
      const isAkFile = file.name.endsWith('.ak');
      if (!isAkFile) {
        this.$message.error('请上传生成的 .ak 文件');
      }
      return isAkFile;
    },
    // // 提交数据时
    handleChange(file, fileList) {
      // 在上传前检查文件类型
      const isAkFile = file.name.endsWith('.ak'); // 只允许上传 .ak 文件
      if (!isAkFile) {
        this.$message.error('只能上传.ak文件！');
        return false; // 阻止文件上传
      }
      // 更新文件列表
      this.fileList = fileList;

      // 创建 FormData 对象
      const formData = new FormData();

      // 将文件添加到 FormData 中
      this.fileList.forEach(file => {
        formData.append('files', file.raw); // 'files[]' 是后端接收的字段名，依据实际情况调整
      });

      console.log("输出文件检查", formData);

      // 显示加载动画
      const loading = this.$loading({
        lock: true,               // 锁屏
        text: '正在上传文件...',   // 加载文字
        spinner: 'el-icon-loading', // 使用 Element 的加载图标
        background: 'rgba(0, 0, 0, 0.7)' // 背景颜色
      });

      // 使用 fetch 或 axios 提交 FormData
      fetch(activate.activateToLoad, {
        method: 'POST',
        body: formData
      })
        .then(response => response.json())
        .then(data => {
          // 关闭加载动画
          loading.close();

          // 成功提示
          // this.$message.success('文件上传成功！');
          // this.$message.success('正在前往登录页！');
          if (data.code == 200) {
            this.$message.success(data.msg)
            // 执行后续操作
            // this.getShowMsg();
            // this.activateOpen = true
          } else {
            this.$message.warning(data.msg)
          }
          // console.log('上传结果:', data);

          setTimeout(() => {
            this.getJudgment();
          }, 3000);
        })
        .catch(error => {
          // 关闭加载动画
          loading.close();

          // 上传失败提示
          this.$message.error('上传失败！');
          console.error('上传错误:', error);
        });
    },
    // 登陆
    handleLogin() {
      this.$refs.loginForm.validate(valid => {
        if (valid) {
          axiosLogin
            .get(this.$url.url_5000 + "/user_view/login", { withcredentials:true,params: { ...this.form } })
            .then((response) => {
              // console.log(response);
              if (response.data.code === 200) {
                this.$message({
                  message: response.data.msg,
                  type: "success",
                });
                // this.$store.commit('setId',response.data.session.id)
                // this.$store.commit('setUser_id',response.data.session.user_id)
                // Cookies.set('session', response.data.session.id, { expires: 1 , path: '/',httpOnly: true  }); // 设置cookie有效期为7天
                this.$store.commit('setToken', response.data.access_token)
                this.$store.commit('setUserInfo', response.data.user_id)
                this.$store.commit('userRoleName', response.data.user_name)
                this.$store.commit('setUserInfos', response.data.user_role_id)
                this.$router.push('/')
              } else {
                this.$message({
                  message: response.data.msg,
                  type: "warning",
                });
                // if (this.system == 'JY') {
                //   this.captcha()
                // }
              }
            })
            .catch(function (response) {
              console.log(response);
            });
        }
      })
    },
    //验证码
    captcha(){
      this.captchaImg = '';
      axiosLogin
        .get(this.$url.url_5000 + "/captcha", {  responseType: 'blod',params: { } })
        .then((response) => {
          console.log(response)
          if (response.status === 200) {
            this.captchaImg = response.request.responseURL;
          } else {
            this.$message({
              message: response.data.msg,
              type: "warning",
            });
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 系统激活判断
    getJudgment() {
      // 首先进行系统判断，探放水版本不需要激活
      if (this.system == 'JY') {
        this.$http.get(loginApi.activateJudgment)
          .then(response => {
            if (response.data.code == 200) {
              this.activateOpen = true
              this.captcha()
            }else if (response.data.code == 400) {
              this.activateOpen = false
            } 
          })
          .catch(rek => {
            console.log(rek);
          })
      } else if (this.system == 'TFS') {
        this.activateOpen = true
      }
    }
  }
};
</script>
  
